Rules.InvariantScript:
Set(showEmergencyPopup, true);
Set(waitingForNextEmergency, false);

Set(emergencyAge, RandBetween(18, 80));

Set(
    emergencyGender,
    Index(
        ["Male", "Female"],
        RandBetween(1, 2)
    ).Value
);

Set(
    medicalCondition,
    Index(
        [
            "None reported",
            "I fell and broke my ankle",
            "Chest pain",
            "Difficulty breathing",
            "Feeling dizzy and weak",
            "Possible allergic reaction",
            "Bleeding from arm",
            "Severe headache",
            "Sprained knee",
            "Unconscious person reported",
            "Panic attack",
            "Burn injury"
        ],
        RandBetween(1, 12)
    ).Value
);

Set(
    emergencyLocation,
    Index(
        [
            "Ascot Avenue, Zetland",
            "George Street, Sydney CBD",
            "City Road, Camperdown",
            "Parramatta Road, Glebe",
            "King Street, Newtown",
            "Oxford Street, Darlinghurst",
            "Cleveland Street, Redfern",
            "Harris Street, Pyrmont",
            "Anzac Parade, Kensington",
            "Bourke Street, Surry Hills"
        ],
        RandBetween(1, 10)
    ).Value
);

Set(
    emergencyDistance,
    Round(RandBetween(1, 30) / 10, 1)
);

Set(
    reportedSeconds,
    RandBetween(10, 120)
);

Set(
    emergencyType,
    Index(
        [
            "Medical emergency",
            "Injury",
            "Fainting",
            "Breathing difficulty",
            "Security threat",
            "Lost person",
            "Fire alert"
        ],
        RandBetween(1, 7)
    ).Value
);

Set(
    vSavedEmergency,
    Patch(
        Incidents_2,
        Defaults(Incidents_2),
        {
            Title: "Emergency Request",
            PatientAge: emergencyAge,
            PatientGender: {Value: emergencyGender},
            ApproximateLocation: emergencyLocation,
            DistanceKm: emergencyDistance,
            EmergencyType: {Value: emergencyType},
            ReportedSeconds: reportedSeconds,
            MedicalCondition: medicalCondition,
            Statues: {Value: "Pending"}
        }
    )
)

Set(vAcceptedAge, emergencyAge);
Set(vAcceptedGender, emergencyGender);
Set(vAcceptedApproxLocation, emergencyLocation);
Set(vAcceptedDistance, emergencyDistance);
Set(vAcceptedEmergencyType, emergencyType);
Set(vAcceptedReportedSeconds, reportedSeconds);
Set(vAcceptedMedicalCondition, medicalCondition);

If(
    vAcceptedGender = "Male",
    Set(
        vAcceptedName,
        Index(
            [
                "Jack Thompson",
                "Oliver Harris",
                "Noah Wilson",
                "William Parker",
                "Thomas Mitchell",
                "Lachlan Cooper",
                "Henry Walker",
                "Charlie Bennett"
            ],
            RandBetween(1, 8)
        ).Value
    ),
    Set(
        vAcceptedName,
        Index(
            [
                "Charlotte Wilson",
                "Olivia Harris",
                "Amelia Parker",
                "Mia Thompson",
                "Isla Walker",
                "Ava Mitchell",
                "Matilda Cooper",
                "Sophie Bennett"
            ],
            RandBetween(1, 8)
        ).Value
    )
);

Set(
    vResponderName,
    Index(
        [
            "Daniel Brooks",
            "Sophie Turner",
            "Ryan Mitchell",
            "Emily Carter",
            "Ben Walker",
            "Grace Wilson",
            "Liam Parker",
            "Chloe Bennett"
        ],
        RandBetween(1, 8)
    ).Value
);

Set(
    vAcceptedExactLocation,
    Index(
        [
            "Building A, Level 2, Room 204",
            "Main entrance near security desk",
            "Library entrance, left side",
            "Car park level B1, near lift",
            "Food court, table area",
            "Sports field, north gate",
            "Lecture hall 3, front row",
            "Near bus stop, platform 2"
        ],
        RandBetween(1, 8)
    ).Value
);

Set(vEstimatedTime, RandBetween(1, 15));

Set(
    vSavedEmergency,
    Patch(
        Incidents_2,
        LookUp(Incidents_2, ID = vSavedEmergency.ID),
        {
            PatientName: vAcceptedName,
            ExactLocation: vAcceptedExactLocation,
            AssignedResponder: vResponderName,
            EstimatedTime: vEstimatedTime,
            Statues: {Value: "Accepted"}
        }
    )
);

Notify("Emergency accepted", NotificationType.Success);

Navigate(AcceptedEmergencyScreen, ScreenTransition.Fade)

ControlPropertyState.AutoRuleBindingString:
Set(
    vAcceptedExactLocation,
    Index(
        [
            "Building A, Level 2, Room 204",
            "Main entrance near security desk",
            "Library entrance, left side",
            "Car park level B1, near lift",
            "Food court, table area",
            "Sports field, north gate",
            "Lecture hall 3, front row",
            "Near bus stop, platform 2"
        ],
        RandBetween(1, 8)
    ).Value
);

Set(vAcceptedName, emergencyPersonName);
Set(vAcceptedAge, emergencyAge);
Set(vAcceptedGender, emergencyGender);
Set(vAcceptedApproxLocation, emergencyLocation);
Set(vAcceptedDistance, emergencyDistance);
Set(vAcceptedEmergencyType, emergencyType);
Set(vAcceptedReportedSeconds, reportedSeconds);
Set(vAcceptedMedicalCondition, medicalCondition);

Patch(
    Incidents,
    Defaults(Incidents),
    {
        Title: "Emergency Request",
        PatientName: emergencyPersonName,
        PatientAge: emergencyAge,
        PatientGender: {Value: emergencyGender},
        ApproximateLocation: emergencyLocation,
        ExactLocation: vAcceptedExactLocation,
        DistanceKm: emergencyDistance,
        EmergencyType: {Value: emergencyType},
        ReportedSeconds: reportedSeconds,
        MedicalCondition: medicalCondition,
        AssignedResponder: responderName,
        EstimatedTime: estimatedTime,
        Statues: {Value: "Accepted"}
    }
);

Notify("Emergency accepted and saved", NotificationType.Success);

Navigate(AcceptedEmergencyScreen, ScreenTransition.Fade)
